export async function load(url,context,next){const result=await next(url,context);if(url.endsWith('/production/src/primitives.mjs')&&process.env.AXIS_MUTATION==='ink')return {...result,source:String(result.source).replace('c.fillText(str,x,y);',"if(opts.role!=='matrix-axis')c.fillText(str,x,y);")};if(url.endsWith('/production/src/scenes.mjs')){let source=String(result.source);const mutation=process.env.AXIS_MUTATION;if(mutation==='owner-column')source=source.replace('+(i===1?40*Math.sin(Math.PI*p):0)','');if(mutation==='owner')source=source.replace('mix(565,1100,clamp(p*1.3)),699+7*ramp(p,0,.15)-30*ramp(p,.5,.5)','mix(565,1100,p),mix(699,676,p)');if(mutation==='card')source=source.replace('rowY-14*move','rowY');if(mutation==='leader')source=source.replace('mix(900,350,move)','colY+mix(114,70,move)');if(mutation==='small')source=source.replace("tx(c,text,x,y,31,700", "tx(c,text,x,y,23,700");if(mutation==='omit')source=source.replace("{role:'matrix-axis'}", "{role:'matrix-axis',record:false}");if(mutation==='swap')source=source.replace("const text=resolveCastText(kind==='red'", "const text=resolveCastText(kind!=='red'");return {...result,source};}return result;}
